window.pdfMake = window.pdfMake || {};
window.pdfMake.vfs = window.pdfMake.vfs || {};
window.pdfMake.vfs['Raavi-Regular.ttf'] = '';
window.pdfMake.vfs['Raavi-Bold.ttf'] = '';
window.pdfMake.fonts = window.pdfMake.fonts || {};
